# ============================================================
# 2. CANONICAL SENSOR CONFIGURATION & REPO ASSETS
# ============================================================
# Canonical positions strictly aligned with the room heatmap:
# Horizontal (x_plot, Length): 0 to 9.0 m | Vertical (y_plot, Width): 0 to 4.0 m
ROA_NODES_META = {
    887:  {"code": "S1", "name": "Sensor 1", "x_plot": 6.75, "y_plot": 2.75, "z": 1.50, "zone": "Office North"},
    672:  {"code": "S2", "name": "Sensor 2", "x_plot": 2.75, "y_plot": 2.75, "z": 1.50, "zone": "Office South"},
    63:   {"code": "S3", "name": "Sensor 3", "x_plot": 4.25, "y_plot": 1.75, "z": 2.50, "zone": "Ceiling Center"},
    1036: {"code": "S4", "name": "Sensor 4", "x_plot": 1.25, "y_plot": 1.25, "z": 2.00, "zone": "Server Pod"},
    1129: {"code": "S5", "name": "Sensor 5", "x_plot": 5.50, "y_plot": 1.75, "z": 2.00, "zone": "Meeting Room"},
}
ROA_NODE_IDS = list(ROA_NODES_META.keys())


@st.cache_data
def load_case_info():
    candidates = [
        Path("Case Info 200 DesignPoints - 최종본.xlsx"),
        Path("Case Info 200 DesignPoints.xlsx"),
    ]
    for p in candidates:
        if p.exists():
            try:
                df = pd.read_excel(p, skiprows=1)
                df.columns = [str(c).strip() for c in df.columns]
                return df
            except Exception:
                pass
    return None


@st.cache_resource
def load_surrogate_model():
    p = Path("best_deploy.pt")
    if p.exists():
        try:
            return torch.load(p, map_location="cpu")
        except Exception:
            pass
    return None


@st.cache_resource
def load_reconstruction_basis():
    p = Path("sensor_reconstruction_basis.npz")
    if p.exists():
        try:
            with np.load(p) as data:
                return {k: data[k] for k in data.files}
        except Exception:
            pass
    return None


case_info_df = load_case_info()
model_assets = load_surrogate_model()
basis_assets = load_reconstruction_basis()


# ============================================================
# 3. SESSION STATE & NAVIGATION ROUTER
# ============================================================
VALID_VIEWS = ["INTRO", "HOME", "HEAT_LOAD", "RESULTS"]

if "app_view" not in st.session_state or st.session_state.app_view not in VALID_VIEWS:
    st.session_state.app_view = "INTRO"

# INTRO 이미지의 실제 버튼 영역을 누르면 ?enter=1 로 들어옵니다.
# 이 값을 감지해 기존 HOME 화면으로 이동합니다.
if st.query_params.get("enter") == "1":
    st.session_state.app_view = "HOME"
    st.query_params.clear()

if "selected_dp" not in st.session_state:
    st.session_state.selected_dp = "DP 0"

if "z_plane" not in st.session_state:
    st.session_state.z_plane = 1.5
# HOME 화면에서는 측정 높이 선택을 사용하지 않고 1.5m로 고정합니다.
st.session_state.z_plane = 1.5

if "target_temp" not in st.session_state:
    st.session_state.target_temp = 24.0

# Optimization policy is intentionally fixed in the simplified UI.
st.session_state.policy = "Balanced (균형)"

if "heat_input_mode" not in st.session_state:
    st.session_state.heat_input_mode = "간편 단계"

for k, v in {"p_ext": "보통", "p_meet": "보통", "p_serv": "보통", "p_work": "보통"}.items():
    if k not in st.session_state:
        st.session_state[k] = v

if "has_run_optimization" not in st.session_state:
    st.session_state.has_run_optimization = False

if "optimized_results" not in st.session_state:
    st.session_state.optimized_results = {
        "status": "FEASIBLE",
        "vane": "Middle (M)",
        "flow": "40 CMM",
        "temp": "12 °C",
        "mean_temp": 23.8,
        "p95_temp": 24.5,
        "zone_spread": 1.42,
        "hot_fraction": 1.8,
        "cold_fraction": 0.5,
        "q_proxy": 13.8,
        "policy_used": "Balanced (균형)",
    }

# ============================================================
# INTRO SCREEN ASSET (embedded in this single Python file)
# ============================================================
INTRO_IMAGE_WEBP_B64 = """"""

if st.session_state.app_view == "INTRO":
    st.markdown(
        """
        <style>
        /* INTRO: make the target artwork fill the phone canvas exactly. */
        .stApp {
            background: #ffffff !important;
        }

        .block-container {
            max-width: 440px !important;
            padding: 0 !important;
            margin: 0.45rem auto 0 auto !important;
            background: transparent !important;
            border: none !important;
            border-radius: 0 !important;
            box-shadow: none !important;
        }

        /* Remove Streamlit's vertical spacing around the image HTML. */
        [data-testid="stVerticalBlock"] {
            gap: 0 !important;
        }

        .coollins-intro-target {
            position: relative;
            width: 100%;
            line-height: 0;
            overflow: hidden;
        }

        .coollins-intro-target img {
            display: block;
            width: 100%;
            height: auto;
            margin: 0;
            padding: 0;
            user-select: none;
            -webkit-user-drag: none;
        }

        /* Transparent real click target placed exactly over the button in the artwork. */
        .coollins-intro-enter {
            position: absolute;
            left: 8.3%;
            top: 87.45%;
            width: 82.0%;
            height: 8.55%;
            display: block;
            border-radius: 18px;
            cursor: pointer;
            text-decoration: none !important;
            background: rgba(0,0,0,0.001);
            z-index: 10;
            outline: none;
            -webkit-tap-highlight-color: transparent;
        }

        .coollins-intro-enter:focus-visible {
            outline: 2px solid #38bdf8;
            outline-offset: -5px;
        }
        </style>
        """,
        unsafe_allow_html=True,
    )

dp_options = (
    case_info_df["Name"].dropna().tolist()
    if (case_info_df is not None and "Name" in case_info_df.columns)
    else [f"DP {i}" for i in range(200)]
)


# ============================================================
# 4. 2D SPATIAL GRID & THERMAL SIMULATION ENGINE
# ============================================================
# Horizontal axis = Length (0.25 to 8.75 m) | Vertical axis = Width (0.25 to 3.75 m)
grid_len_axis = np.linspace(0.25, 8.75, 45)
grid_wid_axis = np.linspace(0.25, 3.75, 25)
mesh_len, mesh_wid = np.meshgrid(grid_len_axis, grid_wid_axis)

stage_to_watt = {"낮음": -1.0, "보통": 0.0, "높음": 1.8}
ext_shift = stage_to_watt.get(st.session_state.get("p_ext", "보통"), 0.0)
meet_shift = stage_to_watt.get(st.session_state.get("p_meet", "보통"), 0.0)
serv_shift = stage_to_watt.get(st.session_state.get("p_serv", "보통"), 0.0)
work_shift = stage_to_watt.get(st.session_state.get("p_work", "보통"), 0.0)

match = re.search(r"\d+", str(st.session_state.selected_dp))
dp_id = int(match.group(0)) if match else 0

# Base thermal field
base_dist = 22.0 + (dp_id % 3) * 0.5

# Physical heat source plumes mapped to respective sensor locations
server_plume = (1.6 + serv_shift) * np.exp(-((mesh_len - 1.25) ** 2 + (mesh_wid - 1.25) ** 2) / 2.0)
solar_drift = (1.3 + ext_shift) * np.exp(-((mesh_len - 6.75) ** 2 + (mesh_wid - 2.75) ** 2) / 3.0)
meet_load = (1.1 + meet_shift) * np.exp(-((mesh_len - 5.50) ** 2 + (mesh_wid - 1.75) ** 2) / 2.0)
z_strat = (st.session_state.z_plane - 1.5) * 0.6

field_current_grid = base_dist + server_plume + solar_drift + meet_load + z_strat
avg_room_temp = float(np.nanmean(field_current_grid))

# Evaluate live virtual readings at each sensor position
sensor_readings = {}
for nid, meta in ROA_NODES_META.items():
    dist = (mesh_len - meta["x_plot"]) ** 2 + (mesh_wid - meta["y_plot"]) ** 2
    idx = np.unravel_index(np.argmin(dist), mesh_len.shape)
    sensor_readings[nid] = float(field_current_grid[idx])


def make_mobile_heatmap(grid_data, height=310):
    fig = go.Figure(
        data=go.Heatmap(
            z=grid_data,
            x=grid_len_axis,  # 0.25 to 8.75m
            y=grid_wid_axis,  # 0.25 to 3.75m
            colorscale="Turbo",
            zmin=18.0,
            zmax=28.0,
            colorbar=dict(title=dict(text="°C", font=dict(size=10, color="#d9f3ff")), thickness=7, len=0.9, x=1.02, tickfont=dict(size=9.5, color="#b7d7e8"), outlinecolor="rgba(174,228,255,0.18)"),
        )
    )

    # Invisible hover targets plus custom navy sensor-shaped icons.
    sx_plot = [meta["x_plot"] for meta in ROA_NODES_META.values()]
    sy_plot = [meta["y_plot"] for meta in ROA_NODES_META.values()]
    hover_texts = [
        f"<b>{meta['name']}</b><br>Zone: {meta['zone']}<br>Coords: (L={meta['x_plot']:.2f}, W={meta['y_plot']:.2f})m<br>Live: {sensor_readings.get(nid, 0.0):.2f}°C"
        for nid, meta in ROA_NODES_META.items()
    ]

    fig.add_trace(
        go.Scatter(
            x=sx_plot,
            y=sy_plot,
            mode="markers",
            marker=dict(size=24, color="rgba(0,0,0,0)", line=dict(width=0)),
            hovertext=hover_texts,
            hoverinfo="text",
            showlegend=False,
        )
    )

    sensor_icon_uri = f"data:image/png;base64,{SENSOR_ICON_B64}"
    for x_pos, y_pos in zip(sx_plot, sy_plot):
        fig.add_layout_image(
            dict(
                source=sensor_icon_uri,
                x=x_pos,
                y=y_pos,
                xref="x",
                yref="y",
                sizex=0.46,
                sizey=0.38,
                xanchor="center",
                yanchor="middle",
                sizing="contain",
                opacity=1.0,
                layer="above",
            )
        )

    fig.update_layout(
        title=dict(text="", font=dict(size=1)),
        showlegend=False,
        xaxis=dict(range=[0.0, 9.0], showgrid=False, zeroline=False, showticklabels=False),
        yaxis=dict(range=[0.0, 4.0], showgrid=False, zeroline=False, showticklabels=False),
        margin=dict(l=0, r=6, t=0, b=0),
        height=height,
        plot_bgcolor="rgba(0,0,0,0)",
        paper_bgcolor="rgba(0,0,0,0)",
        autosize=True,
    )
    return fig


